codeExample:
/* 
  The beauty of GraphQL: The response shape matches the query shape exactly. 
*/

// The Client's Query (Sent via POST body)
query {
  user(id: 123) {
    name
    email
    posts(limit: 2) {
      title
    }
  }
}

// The Server's Response (No age, no password, no extra junk. Just what was asked for.)
{
  "data": {
    "user": {
      "name": "John",
      "email": "john@test.com",
      "posts": [
        { "title": "Hello World" },
        { "title": "GraphQL is cool" }
      ]
    }
  }
}
